class Solution:
    def minTotalDistance(self, grid: list[list[int]]) -> int:
        rows, cols = [], []
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    rows.append(i)
                    cols.append(j)
        cols.sort()
        def min_dist(points):
            mid = points[len(points)//2]
            return sum(abs(p - mid) for p in points)
        return min_dist(rows) + min_dist(cols)

